// Package lru implements a fixed-capacity least-recently-used cache.
package lru

// sentinel is the index of the list head node. next[sentinel] is the most
// recently used entry and prev[sentinel] the least recently used one.
const sentinel = 0

type node[V any] struct {
	key        string
	value      V
	prev, next int32
}

// Cache is a fixed-capacity LRU cache keyed by strings. It is backed by a hash
// map and an intrusive doubly linked list stored in a slice, so every
// operation runs in O(1) expected time. A Cache is not safe for concurrent use.
type Cache[V any] struct {
	capacity int
	index    map[string]int32
	nodes    []node[V] // nodes[0] is the sentinel
	free     []int32   // indices of released nodes available for reuse
}

// New returns an empty cache that holds at most capacity entries.
// It panics if capacity is less than 1.
func New[V any](capacity int) *Cache[V] {
	if capacity < 1 {
		panic("lru: capacity must be at least 1")
	}
	// Grow storage on demand so a large capacity with few keys stays cheap.
	hint := min(capacity, 1<<16)
	c := &Cache[V]{
		capacity: capacity,
		index:    make(map[string]int32, hint),
		nodes:    make([]node[V], 1, hint+1),
	}
	return c
}

// Len reports the number of entries held.
func (c *Cache[V]) Len() int { return len(c.index) }

// Get returns the value stored for key and marks it most recently used.
// The boolean reports whether the key was present.
func (c *Cache[V]) Get(key string) (V, bool) {
	i, ok := c.index[key]
	if !ok {
		var zero V
		return zero, false
	}
	c.moveToFront(i)
	return c.nodes[i].value, true
}

// Set inserts or overwrites key and marks it most recently used, evicting the
// least recently used entry if the cache would exceed its capacity.
func (c *Cache[V]) Set(key string, value V) {
	if i, ok := c.index[key]; ok {
		c.nodes[i].value = value
		c.moveToFront(i)
		return
	}
	if len(c.index) == c.capacity {
		c.remove(c.nodes[sentinel].prev)
	}
	i := c.alloc()
	c.nodes[i].key = key
	c.nodes[i].value = value
	c.index[key] = i
	c.pushFront(i)
}

// Delete removes key and reports whether it was present.
func (c *Cache[V]) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

func (c *Cache[V]) alloc() int32 {
	if n := len(c.free); n > 0 {
		i := c.free[n-1]
		c.free = c.free[:n-1]
		return i
	}
	c.nodes = append(c.nodes, node[V]{})
	return int32(len(c.nodes) - 1)
}

func (c *Cache[V]) remove(i int32) {
	delete(c.index, c.nodes[i].key)
	c.unlink(i)
	c.nodes[i] = node[V]{} // drop references so they can be collected
	c.free = append(c.free, i)
}

func (c *Cache[V]) moveToFront(i int32) {
	if c.nodes[sentinel].next == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache[V]) unlink(i int32) {
	p, n := c.nodes[i].prev, c.nodes[i].next
	c.nodes[p].next = n
	c.nodes[n].prev = p
}

func (c *Cache[V]) pushFront(i int32) {
	first := c.nodes[sentinel].next
	c.nodes[i].prev = sentinel
	c.nodes[i].next = first
	c.nodes[first].prev = i
	c.nodes[sentinel].next = i
}

package lru

import "testing"

func TestEvictsLeastRecentlyUsed(t *testing.T) {
	c := New[string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if n := c.Len(); n != 2 {
		t.Fatalf("Len() = %d; want 2", n)
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New[int](2)
	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("a", 9)
	c.Set("c", 3)
	if v, ok := c.Get("a"); !ok || v != 9 {
		t.Fatalf("Get(a) = %d, %v; want 9, true", v, ok)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New[int](1)
	if c.Delete("x") {
		t.Fatal("Delete on empty cache reported true")
	}
	for i := range 100 {
		c.Set("x", i)
		if !c.Delete("x") {
			t.Fatal("Delete(x) = false; want true")
		}
	}
	if n := len(c.nodes); n != 2 {
		t.Fatalf("node storage grew to %d; want 2", n)
	}
	if c.Len() != 0 {
		t.Fatalf("Len() = %d; want 0", c.Len())
	}
}

// Command app simulates an LRU cache driven by commands read from standard
// input. See SPEC.md for the input format.
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/internal/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return fmt.Errorf("reading input: %w", err)
	}

	header, rest, _ := bytes.Cut(input, []byte{'\n'})
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(header)))
	if err != nil {
		return fmt.Errorf("invalid capacity: %w", err)
	}
	if capacity < 1 {
		return errors.New("invalid capacity: must be at least 1")
	}

	out := bufio.NewWriterSize(w, 1<<16)
	// Values are kept as subslices of input, which stays alive for the whole
	// run anyway; this avoids an allocation per SET.
	cache := lru.New[[]byte](capacity)

	for len(rest) > 0 {
		var line []byte
		line, rest, _ = bytes.Cut(rest, []byte{'\n'})
		line = bytes.TrimSuffix(line, []byte{'\r'})
		execute(cache, line, out)
	}
	if err := out.Flush(); err != nil {
		return fmt.Errorf("writing output: %w", err)
	}
	return nil
}

// execute applies one command line to cache, writing any result to out.
// Blank and unrecognised lines are ignored.
func execute(cache *lru.Cache[[]byte], line []byte, out *bufio.Writer) {
	cmd, args, _ := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		if key, value, ok := bytes.Cut(args, []byte{' '}); ok {
			cache.Set(string(key), value)
		}
	case "GET":
		if value, ok := cache.Get(string(args)); ok {
			out.Write(value)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if cache.Delete(string(args)) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		out.WriteString(strconv.Itoa(cache.Len()))
		out.WriteByte('\n')
	}
}
